import React, { useState, useEffect } from "react";
import { Trans, useTranslation } from "gatsby-plugin-react-i18next";
import { Link } from "gatsby";
import { FiMenu, FiX } from "react-icons/fi";
import { FaArrowUp } from "react-icons/fa";
import { motion, AnimatePresence } from "framer-motion";
import { isHome } from '../constants/constants';

interface NavProps {
  data?: {
    menu: string[];
  };
}

const Navigation: React.FC<NavProps> = ({ data }) => {
  const { t } = useTranslation();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [showBackToTop, setShowBackToTop] = useState(false);
  const isHomePage = isHome();

  if (!data || !data.menu) {
    return null;
  }

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 100) {
        setShowBackToTop(true);
      } else {
        setShowBackToTop(false);
      }
    };
    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  return (
    <nav className={styles.container}>
      {isHomePage && <button onClick={toggleMenu} className={styles.burgerButton}>
        {isMenuOpen ? (
          <FiX className="text-secondary fixed right-4 z-[70] top-4" size={36} />
        ) : (
          <FiMenu className="text-secondary mx-8" size={36}  aria-label="Toggle menu" />
        )}
      </button>}

      <AnimatePresence>
        <motion.ul
          initial="closed"
          animate="open"
          exit="closed"
          className={styles.buttonsWrapper}
        >
          {data.menu.map((item: string, index: number) => (
            <li key={index} className={styles.buttonsContainer}>
              <Link activeClassName={styles.active} to={`/${item}`} className={styles.buttons} onClick={() => setIsMenuOpen(false)}>
                <Trans i18nKey={`menu.${item}`}>{t(`menu.${item}`)}</Trans>
              </Link>
            </li>
          ))}
        </motion.ul>
      </AnimatePresence>

      {showBackToTop && (
        <button onClick={scrollToTop} className={styles.backToTopButton}>
          <FaArrowUp size={20} />
        </button>
      )}
    </nav>
  );
};

export default Navigation;

const styles = {
  container:
    "inline-block justify-between items-center px-4 py-2 mx-0 sm:mx-8 z-10",
  burgerButton: "md:hidden block focus:outline-none mx-auto ",
  buttonsWrapper:
    "flex flex-col md:flex-row justify-evenly items-center w-full fixed sm:relative left-0 top-0 py-8 sm:py-0 gap-4",
  buttonsContainer: "bg-primary hover:bg-accent sm:my-0 rounded-lg",
  buttons: "text-accent hover:text-neutral px-8 py-2 text-lg shadow-xl shadow-warning-500 rounded-lg",
  menuOpen: "bg-primary sm:bg-transparent block md:flex",
  menuClosed: "hidden md:flex",
  backToTopButton:
    "text-neutral bg-accent fixed bottom-4 right-4 p-2 rounded-full shadow-lg z-50",
    active: "bg-accent text-neutral",
};
